  1	/* ============================================================
  2	   views/project-detail.js — Project Detail view
  3	   Sections 4b–4d of the MCP Server Dashboard SPA
  4	   Depends on: API, Router, marked, escapeHtml, formatDate,
  5	               statusBadge, showLoading, showError,
  6	               OrchestratorWidgets (js/orchestrator-widgets.js),
  7	               UI (components.js)
  8	   ============================================================ */
  9	
 10	// Module-scoped log-preview cleanup registry.
 11	// Each renderProjectDetail() call drains this array before creating new widgets.
 12	var _pdLogPreviewCleanups = [];
 13	
 14	/* ----------------------------------------------------------
 15	   4b. View: Plan Document
 16	   ---------------------------------------------------------- */
 17	function extractSynopsis(markdown) {
 18	  var match = markdown.match(/## Summary\s*\n([\s\S]*?)(?=\n## |\n---|\s*$)/);
 19	  return match ? match[1].trim() : null;
 20	}
 21	
 22	async function renderPlan(app, repo, slug) {
 23	  app.innerHTML = '<p class="loading">Loading plan\u2026</p>';
 24	  try {
 25	    var result = await API.getPlanDocument(repo, slug);
 26	    var html = marked.parse(result.content);
 27	    app.innerHTML =
 28	      breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
 29	      '<div class="plan-content">' + html + '</div>';
 30	  } catch (err) {
 31	    if (err && err.code === 'NOT_FOUND') {
 32	      app.innerHTML =
 33	        breadcrumb().projects().project(repo, slug).leaf('Plan').html() +
 34	        '<p class="empty-state">Plan document not available for this project.</p>';
 35	    } else {
 36	      app.innerHTML = UI.banner('error', 'Failed to load plan document.');
 37	    }
 38	  }
 39	}
 40	
 41	/* ----------------------------------------------------------
 42	   4b-ii. View: Synthesis Document
 43	   ---------------------------------------------------------- */
 44	async function renderSynthesis(app, repo, slug) {
 45	  app.innerHTML = '<p class="loading">Loading synthesis\u2026</p>';
 46	  try {
 47	    var result = await API.getSynthesisDocument(repo, slug);
 48	    var html = marked.parse(result.content);
 49	    app.innerHTML =
 50	      breadcrumb().projects().project(repo, slug).leaf('Synthesis').html() +
 51	      '<div class="synthesis-content">' + html + '</div>';
 52	  } catch (err) {
 53	    if (err && err.code === 'NOT_FOUND') {
 54	      app.innerHTML =
 55	        breadcrumb().projects().project(repo, slug).leaf('Synthesis').html() +
 56	        '<p class="empty-state">Synthesis document not available for this project.</p>';
 57	    } else {
 58	      app.innerHTML = UI.banner('error', 'Failed to load synthesis document.');
 59	    }
 60	  }
 61	}
 62	
 63	/* ----------------------------------------------------------
 64	   4c. View: Project Detail
 65	   ---------------------------------------------------------- */
 66	
 67	// Abbreviations for pipeline stage types
 68	var STAGE_ABBREV = {
 69	  'implementation':     'DEV',
 70	  'qa':                 'QA',
 71	  'security-audit':     'SEC',
 72	  'code-review':        'REV',
 73	  'release-engineering':'REL',
 74	  'documentation':      'DOC'
 75	};
 76	
 77	function buildPipelineTrack(overviewEntry) {
 78	  if (!overviewEntry || !overviewEntry.pipeline_stages || !overviewEntry.pipeline_stages.length) {
 79	    return '—';
 80	  }
 81	  var badges = overviewEntry.pipeline_stages.map(function (stage) {
 82	    var abbrev = STAGE_ABBREV[stage.type] || stage.type.slice(0, 3).toUpperCase();
 83	    var statusClass = 'stage-pending';
 84	    if (stage.status === 'in-progress') statusClass = 'stage-in-progress';
 85	    else if (stage.status === 'pass')        statusClass = 'stage-pass';
 86	    else if (stage.status === 'fail')        statusClass = 'stage-fail';
 87	    var tooltip = escapeHtml(stage.type) + ' — ' + escapeHtml(stage.agent);
 88	    if (stage.rework_count > 0) tooltip += ' (rework: ' + stage.rework_count + ')';
 89	    var reworkBadge = stage.rework_count > 0
 90	      ? '<span class="rework-indicator" title="Rework count: ' + stage.rework_count + '">' + stage.rework_count + '</span>'
 91	      : '';
 92	    return '<span class="stage-badge ' + statusClass + '" title="' + tooltip + '">' +
 93	      escapeHtml(abbrev) +
 94	      reworkBadge +
 95	    '</span>';
 96	  }).join('');
 97	  return '<div class="pipeline-track">' + badges + '</div>';
 98	}
 99	
100	function buildRunBadges(item, isActive) {

101	  var badges = '';
102	  if (isActive) {
103	    badges += '<span class="badge badge-in-progress">Running</span>';
104	  }
105	  if (item && item.is_dry_run) {
106	    badges += '<span class="badge badge-dry-run">Dry Run</span>';
107	  }
108	  return badges;
109	}
110	
111	/* ----------------------------------------------------------
112	   Orchestrator Toolbar
113	   Renders Kill + Resume buttons into toolbarEl.
114	   Always visible; buttons are disabled (with explanatory
115	   tooltips) when the corresponding action is unavailable.
116	
117	   opts: {
118	     loading:      bool,           — show "Loading…" disabled state
119	     hasActiveRun: bool,           — is there an active run?
120	     queueEntry:   object|null,    — matching queue entry (kill)
121	     runMeta:      object|null,    — run metadata (resume)
122	     meta:         object,         — project meta (plan_path, status)
123	     repo:         string,
124	     slug:         string,
125	     app:          Element,        — root element (re-render after resume)
126	     onKillDone:   Function,       — called after a successful kill
127	   }
128	   ---------------------------------------------------------- */
129	function renderOrchToolbar(toolbarEl, opts) {
130	  if (!toolbarEl) return;
131	  toolbarEl.innerHTML = '';
132	
133	  var loading      = !!opts.loading;
134	  var hasActiveRun = !!opts.hasActiveRun;
135	  var queueEntry   = opts.queueEntry  || null;
136	  var runMeta      = opts.runMeta     || null;
137	  var meta         = opts.meta        || {};
138	  var repo         = opts.repo        || '';
139	  var slug         = opts.slug        || '';
140	  var app          = opts.app         || null;
141	  var onKillDone   = typeof opts.onKillDone === 'function' ? opts.onKillDone : null;
142	
143	  // ── Kill button ─────────────────────────────────────────────────────
144	  var killDisabled = true;
145	  var killTitle    = 'Loading\u2026';
146	  if (!loading) {
147	    if (!hasActiveRun) {
148	      killTitle = 'No active run to kill';
149	    } else if (!queueEntry) {
150	      killTitle = 'Run is active but not found in the queue \u2014 use: node scripts/kill-orchestrator.js --force';
151	    } else {
152	      killDisabled = false;
153	      killTitle    = '';
154	    }
155	  }
156	
157	  if (killDisabled) {
158	    var killBtn = document.createElement('button');
159	    killBtn.type = 'button';
160	    killBtn.className = 'btn btn-danger btn-sm orchestrator-kill-btn';
161	    killBtn.textContent = 'Kill';
162	    killBtn.disabled = true;
163	    if (killTitle) killBtn.title = killTitle;
164	    toolbarEl.appendChild(killBtn);
165	  } else {
166	    toolbarEl.appendChild(
167	      OrchestratorWidgets.renderKillButton(queueEntry.id, function () {
168	        if (onKillDone) onKillDone();
169	      })
170	    );
171	  }
172	
173	  // ── Resume button ────────────────────────────────────────────────────
174	  var resumeDisabled = true;
175	  var resumeTitle    = 'Loading\u2026';
176	  if (!loading) {
177	    if (hasActiveRun) {
178	      resumeTitle = 'Cannot resume while a run is active';
179	    } else if (!meta.plan_path) {
180	      resumeTitle = 'No plan path configured for this project';
181	    } else if (meta.status === 'COMPLETE') {
182	      resumeTitle = 'Project is already complete \u2014 nothing to resume';
183	    } else if (meta.status === 'ARCHIVED') {
184	      resumeTitle = 'Project is archived';
185	    } else if (!runMeta || !runMeta.thread_id) {
186	      resumeTitle = 'No interrupted run found';
187	    } else if (runMeta.dry_run === true) {
188	      resumeTitle = 'Dry runs cannot be resumed';
189	    } else if (runMeta.result === 'SUCCESS') {
190	      resumeTitle = 'Last run completed successfully \u2014 nothing to resume';
191	    } else {
192	      resumeDisabled = false;
193	      resumeTitle    = '';
194	    }
195	  }
196	
197	  var resumeBtn = document.createElement('button');
198	  resumeBtn.id   = 'orch-resume-btn';
199	  resumeBtn.type = 'button';
200	  resumeBtn.className = 'btn btn-resume btn-sm';
201	  resumeBtn.textContent = 'Resume';
202	  resumeBtn.disabled = resumeDisabled;
203	  if (resumeTitle) resumeBtn.title = resumeTitle;
204	
205	  if (!resumeDisabled) {
206	    var threadId = runMeta.thread_id;
207	    var planPath = meta.plan_path;
208	
209	    resumeBtn.addEventListener('click', function () {
210	      resumeBtn.disabled = true;
211	      resumeBtn.textContent = 'Resuming\u2026';
212	      // Remove any stale error banner.
213	      var prevErr = document.getElementById('orch-resume-error');
214	      if (prevErr) prevErr.remove();
215	
216	      API.orchestratorStart(planPath, false, threadId).then(function (result) {
217	        if (result && result.started) {
218	          resumeBtn.textContent = 'Launching\u2026';
219	          var pollResume = function () {
220	            API.orchestratorGetQueue().then(function (queue) {
221	              var hasActiveEntry = Array.isArray(queue) && queue.some(function (entry) {
222	                return entry && (entry.effectiveStatus === 'pending' ||
223	                                 entry.effectiveStatus === 'started');
224	              });
225	              if (hasActiveEntry) {
226	                Router._clearPolling();
227	                if (app) renderProjectDetail(app, repo, slug);
228	              }
229	            }).catch(function () { /* keep polling */ });
230	          };
231	          Router._setPolling(pollResume, 3000);
232	        } else {
233	          resumeBtn.disabled = false;
234	          resumeBtn.textContent = 'Resume';
235	          var errEl = document.getElementById('orch-resume-error');
236	          if (!errEl) {
237	            errEl = document.createElement('p');
238	            errEl.id = 'orch-resume-error';
239	            errEl.className = 'error-banner';
240	            toolbarEl.insertAdjacentElement('afterend', errEl);
241	          }
242	          errEl.textContent = 'Resume could not be started.';
243	        }
244	      }).catch(function (err) {
245	        resumeBtn.disabled = false;
246	        resumeBtn.textContent = 'Resume';
247	        var errEl = document.getElementById('orch-resume-error');
248	        if (!errEl) {
249	          errEl = document.createElement('p');
250	          errEl.id = 'orch-resume-error';

251	          errEl.className = 'error-banner';
252	          toolbarEl.insertAdjacentElement('afterend', errEl);
253	        }
254	        errEl.textContent = 'Resume failed: ' + (err.message || String(err));
255	      });
256	    });
257	  }
258	
259	  toolbarEl.appendChild(resumeBtn);
260	}
261	
262	/* ----------------------------------------------------------
263	   4c-i. DOM Patch Functions
264	   Targeted compare-and-swap helpers for in-place DOM updates.
265	   Each function performs fresh DOM queries on every invocation —
266	   no element references are cached across poll cycles.
267	   All functions are no-ops when the target element is not found.
268	   ---------------------------------------------------------- */
269	
270	/**
271	 * Update the project status badge in the page header.
272	 * @param {string} newStatus - New WP status string (e.g. 'IN_PROGRESS', 'COMPLETE').
273	 */
274	function _patchProjectStatus(newStatus) {
275	  var container = document.getElementById('project-status-badge');
276	  if (!container) return;
277	  var newHtml = statusBadge(newStatus);
278	  if (container.innerHTML !== newHtml) {
279	    container.innerHTML = newHtml;
280	  }
281	}
282	
283	/**
284	 * Update a single WP row's status badge and pipeline track cells in-place.
285	 * Leaves the WP ID and assigned-to cells untouched.
286	 * @param {string} wpId             - Work package ID (e.g. 'WP-001').
287	 * @param {string} newStatus        - New WP status string.
288	 * @param {string} newPipelineTrack - New pipeline track HTML (from buildPipelineTrack).
289	 */
290	function _patchWpRow(wpId, newStatus, newPipelineTrack) {
291	  var row = document.querySelector('tr[data-wp-id="' + escapeHtml(wpId) + '"]');
292	  if (!row) return;
293	
294	  var statusCell = row.querySelector('.wp-status-cell');
295	  if (statusCell) {
296	    var newStatusHtml = statusBadge(newStatus);
297	    if (statusCell.innerHTML !== newStatusHtml) {
298	      statusCell.innerHTML = newStatusHtml;
299	    }
300	  }
301	
302	  var pipelineCell = row.querySelector('.wp-pipeline-track-cell');
303	  if (pipelineCell) {
304	    if (pipelineCell.innerHTML !== newPipelineTrack) {
305	      pipelineCell.innerHTML = newPipelineTrack;
306	    }
307	  }
308	}
309	
310	/**
311	 * Show or hide the synthesis link row.
312	 * When visible=true and the row exists but is hidden, it is shown.
313	 * When visible=true and the row is absent, it is injected before the WP table.
314	 * When visible=false, the row is hidden.
315	 * @param {boolean} visible         - Whether the synthesis link should be visible.
316	 * @param {string}  [repo]          - Repository name (required when injecting).
317	 * @param {string}  [slug]          - Project slug (required when injecting).
318	 */
319	function _patchSynthesisLink(visible, repo, slug) {
320	  var row = document.getElementById('synthesis-link-row');
321	  if (visible) {
322	    if (row) {
323	      // Ensure the link href is populated if the row was pre-rendered empty.
324	      if (!row.querySelector('.synthesis-link') && repo && slug) {
325	        row.className = 'synthesis-link-row';
326	        row.innerHTML = '<a href="#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/synthesis" class="synthesis-link">View synthesis \u2192</a>';
327	      }
328	      row.style.display = '';
329	    } else if (repo && slug) {
330	      // Inject before the WP table section (card-title "Work Packages").
331	      var wpTitle = document.querySelector('.card-title');
332	      if (wpTitle) {
333	        var newRow = document.createElement('div');
334	        newRow.id = 'synthesis-link-row';
335	        newRow.className = 'synthesis-link-row';
336	        newRow.innerHTML = '<a href="#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) + '/synthesis" class="synthesis-link">View synthesis \u2192</a>';
337	        wpTitle.parentNode.insertBefore(newRow, wpTitle);
338	      }
339	    }
340	  } else {
341	    if (row) {
342	      row.style.display = 'none';
343	    }
344	  }
345	}
346	
347	/**
348	 * Update the health badge text and CSS class.
349	 * @param {{ work_packages_needing_reset: number }} health - Health data object.
350	 */
351	function _patchHealthBadge(health) {
352	  var badge = document.getElementById('health-badge');
353	  if (!badge) return;
354	  if (health.work_packages_needing_reset === 0) {
355	    var newText = '\u2713 All pipelines complete';
356	    var newClass = 'health-badge healthy';
357	    if (badge.textContent !== newText) badge.textContent = newText;
358	    if (badge.className !== newClass) badge.className = newClass;
359	  } else {
360	    var count = health.work_packages_needing_reset;
361	    var newText2 = '\u26a0 ' + count + ' WP' + (count === 1 ? '' : 's') + ' need attention';
362	    var newClass2 = 'health-badge attention';
363	    if (badge.textContent !== newText2) badge.textContent = newText2;
364	    if (badge.className !== newClass2) badge.className = newClass2;
365	  }
366	}
367	
368	/**
369	 * Update the timing info display in-place.
370	 * @param {{ project_elapsed_ms: number, total_active_ms: number, pipeline_runs: number }} timing
371	 */
372	function _patchTimingInfo(timing) {
373	  var container = document.getElementById('timing-info');
374	  if (!container) return;
375	  if (!timing) return;
376	
377	  var durationEl = document.getElementById('timing-duration');
378	  if (durationEl) {
379	    var newDuration = formatDuration(timing.project_elapsed_ms);
380	    if (durationEl.textContent !== newDuration) durationEl.textContent = newDuration;
381	  }
382	
383	  var activeEl = document.getElementById('timing-active');
384	  if (activeEl) {
385	    var newActive = formatDuration(timing.total_active_ms);
386	    if (activeEl.textContent !== newActive) activeEl.textContent = newActive;
387	  }
388	
389	  var runsEl = document.getElementById('timing-runs');
390	  if (runsEl) {
391	    var newRuns = String(timing.pipeline_runs);
392	    if (runsEl.textContent !== newRuns) runsEl.textContent = newRuns;
393	  }
394	}
395	
396	function renderProjectDetail(app, repo, slug) {
397	  // Drain log preview cleanup callbacks from the previous render.
398	  _pdLogPreviewCleanups.forEach(function (fn) { try { fn(); } catch (_) {} });
399	  _pdLogPreviewCleanups = [];
400	
401	  showLoading(app);
402	
403	  Promise.all([
404	    API.getProject(repo, slug),
405	    API.getPlanDocument(repo, slug).catch(function () { return null; }),
406	    API.getWorkPackageOverview(repo, slug).catch(function () { return null; }),
407	  ]).then(function (results) {
408	    var project = results[0];
409	    var planResult = results[1];
410	    var overviewResult = results[2]; // null if request failed (graceful degradation)
411	    var meta = project.meta || {};
412	    var wps = project.work_packages || [];
413	
414	    // Build a fast lookup: work_package_id → overview entry
415	    var overviewMap = {};
416	    if (overviewResult && Array.isArray(overviewResult)) {
417	      overviewResult.forEach(function (entry) {
418	        overviewMap[entry.work_package_id] = entry;
419	      });
420	    }
421	
422	    var useOverview = overviewResult !== null;
423	
424	    var wpRows = wps.map(function (wp) {
425	      var pipelineCell = useOverview
426	        ? buildPipelineTrack(overviewMap[wp.work_package_id])
